#include<iostream>
#include<cstdlib>
#include<sstream>
using namespace std;bool y(string i){if(i=="y")return true;else return false;}int i(string i){ostringstream c;for(int l=0;l<i.length();l++){switch(i[l]){case'0':c<<0;break;case'1':c<<1;break;case'2':c<<2;break;case'3':c<<3;break;case'4':c<<4;break;case'5':c<<5;break;case'6':c<<6;break;case'7':c<<7;break;case'8':c<<8;break;case'9':c<<9;break;}}stringstream v(c.str());int o=0;v>>o;return o;}int main(){int l,c,r,s;string h,u;bool p,o,n=true,e;ostringstream t;cout<<"Length:";cin>>u;l=i(u);if(l==0)l=1;cout<<"Count:";cin>>u;c=i(u);if(c==0)c=1;cout<<"Use time as seed (y/n):";cin>>u;e=y(u);if(e==true){s=time(0);srand(s);}else{cout<<"Seed:";cin>>u;s=i(u);srand(s);}cout<<"Upper characters (y/n):";cin>>u;p=y(u);cout<<"Lower characters (y/n):";cin>>u;o=y(u);if(p==true||o==true){cout<<"Numbers (y/n):";cin>>u;n=y(u);}for(int i=0;i<62;i++){if(i<10&&n==true){t<<char(i+48);}if(i<36&&i>10&&p==true){t<<char(i+55);}if(i>36&&o==true){t<<char(i+61);}}h=t.str();for(int b=0;b<c;b++){for(int a=0;a<l;a++){r=rand()%h.length();cout<<h[r];}cout<<endl;}}